solution.solution.cpp:
#include <algorithm>
#include <cmath>

struct Vector2 { float x, y; };
struct Rectangle { float x, y, width, height; };

struct Game
{
    Rectangle left{ 30, 185, 10, 80 }, right{ 760, 185, 10, 80 };
    Vector2 ball{ 400, 225 }, vel{ 300, 0 };
    float radius{ 8 };
    int leftScore{ 0 }, rightScore{ 0 };
    int winner{ 0 };
};

namespace
{
    constexpr float W{ 800 }, H{ 450 };

    bool circleRect(Vector2 c, float r, const Rectangle& rect)
    {
        const float nx{ std::clamp(c.x, rect.x, rect.x + rect.width) };
        const float ny{ std::clamp(c.y, rect.y, rect.y + rect.height) };
        const float dx{ c.x - nx }, dy{ c.y - ny };
        return dx * dx + dy * dy <= r * r;
    }

    void movePaddle(Rectangle& p, float dir, float dt)
    {
        p.y = std::clamp(p.y + dir * 360.0f * dt, 0.0f, H - p.height);
    }

    void bounce(Game& g, const Rectangle& p, float away)
    {
        const float speed{ std::min(std::sqrt(g.vel.x * g.vel.x + g.vel.y * g.vel.y) * 1.05f, 900.0f) };
        const float offset{ std::clamp((g.ball.y - (p.y + p.height / 2)) / (p.height / 2), -1.0f, 1.0f) };
        const float angle{ offset * 60.0f * 3.14159265f / 180.0f };
        g.vel = { away * speed * std::cos(angle), speed * std::sin(angle) };
        g.ball.x = away > 0 ? p.x + p.width + g.radius : p.x - g.radius;
    }

    void serve(Game& g, float towards)
    {
        g.ball = { W / 2, H / 2 };
        g.vel = { towards * 300.0f, 0 };
    }
}

void update(Game& g, float leftDir, float rightDir, float dt)
{
    if (g.winner != 0) return;
    movePaddle(g.left, leftDir, dt);
    movePaddle(g.right, rightDir, dt);

    g.ball.x += g.vel.x * dt;
    g.ball.y += g.vel.y * dt;

    if (g.ball.y - g.radius < 0) { g.ball.y = g.radius; g.vel.y = std::fabs(g.vel.y); }
    if (g.ball.y + g.radius > H) { g.ball.y = H - g.radius; g.vel.y = -std::fabs(g.vel.y); }

    if (g.vel.x < 0 && circleRect(g.ball, g.radius, g.left)) bounce(g, g.left, 1.0f);
    else if (g.vel.x > 0 && circleRect(g.ball, g.radius, g.right)) bounce(g, g.right, -1.0f);

    if (g.ball.x + g.radius < 0)
    {
        ++g.rightScore;
        serve(g, -1.0f);
    }
    else if (g.ball.x - g.radius > W)
    {
        ++g.leftScore;
        serve(g, 1.0f);
    }
    if (g.leftScore >= 5) g.winner = 1;
    else if (g.rightScore >= 5) g.winner = 2;
}

float computerDir(const Rectangle& paddle, Vector2 ball)
{
    const float centre{ paddle.y + paddle.height / 2 };
    if (ball.y > centre + 10) return 1;
    if (ball.y < centre - 10) return -1;
    return 0;
}

unitTests:
TEST("paddles move and stay inside") {
    Game g; g.vel = { 0, 0 };
    update(g, 1, -1, 0.1f); CHECK_NEAR(g.left.y, 221.0, 1e-3); CHECK_NEAR(g.right.y, 149.0, 1e-3);
    for (int i = 0; i < 100; ++i) update(g, 1, -1, 0.1f);
    CHECK_NEAR(g.left.y, 370.0, 1e-3); CHECK_NEAR(g.right.y, 0.0, 1e-3);
}
TEST("walls bounce") {
    Game g; g.ball = { 400, 10 }; g.vel = { 0, -100 }; update(g, 0, 0, 0.05f);
    CHECK_NEAR(g.ball.y, 8.0, 1e-3); CHECK(g.vel.y > 0);
    g.ball = { 400, 440 }; g.vel = { 0, 100 }; update(g, 0, 0, 0.05f); CHECK_NEAR(g.ball.y, 442.0, 1e-3); CHECK(g.vel.y < 0);
}
TEST("a centre hit goes straight back, faster") {
    Game g; g.ball = { 50, 225 }; g.vel = { -300, 0 }; update(g, 0, 0, 0.01f);
    CHECK_NEAR(g.vel.x, 315.0, 1e-2); CHECK_NEAR(g.vel.y, 0.0, 1e-2); CHECK_NEAR(g.ball.x, 48.0, 1e-3);
}
TEST("an edge hit is angled") {
    Game g; g.ball = { 50, 265 }; g.vel = { -300, 0 }; update(g, 0, 0, 0.01f);
    CHECK_NEAR(g.vel.x, 157.5, 1e-1); CHECK_NEAR(g.vel.y, 272.8, 1e-1);
    Game r; r.ball = { 750, 185 }; r.vel = { 300, 0 }; update(r, 0, 0, 0.01f);
    CHECK_NEAR(r.vel.x, -157.5, 1e-1); CHECK_NEAR(r.vel.y, -272.8, 1e-1); CHECK_NEAR(r.ball.x, 752.0, 1e-3);
}
TEST("speed is capped") { Game g; g.ball = { 50, 225 }; g.vel = { -890, 0 }; update(g, 0, 0, 0.003f); CHECK_NEAR(g.vel.x, 900.0, 1e-2); }
TEST("moving away does not bounce") { Game g; g.ball = { 45, 225 }; g.vel = { 300, 0 }; update(g, 0, 0, 0.001f); CHECK(g.vel.x > 0); CHECK_NEAR(g.vel.x, 300.0, 1e-3); }
TEST("points and serves") {
    Game g; g.ball = { -10, 100 }; g.vel = { -300, 0 }; update(g, 0, 0, 0.01f);
    CHECK_EQ(g.rightScore, 1); CHECK_NEAR(g.ball.x, 400.0, 1e-3); CHECK_NEAR(g.vel.x, -300.0, 1e-3);
    g.ball = { 810, 100 }; g.vel = { 300, 0 }; update(g, 0, 0, 0.01f); CHECK_EQ(g.leftScore, 1); CHECK_NEAR(g.vel.x, 300.0, 1e-3);
}
TEST("first to five") {
    Game g; for (int i = 0; i < 5; ++i) { g.ball = { -20, 100 }; g.vel = { -300, 0 }; update(g, 0, 0, 0.01f); }
    CHECK_EQ(g.winner, 2); const float y = g.left.y; update(g, 1, 0, 1.0f); CHECK_NEAR(g.left.y, y, 1e-6);
}
TEST("computer paddle") { const Rectangle p{ 760, 185, 10, 80 }; CHECK_EQ(computerDir(p, { 0, 300 }), 1.0f); CHECK_EQ(computerDir(p, { 0, 100 }), -1.0f); CHECK_EQ(computerDir(p, { 0, 230 }), 0.0f); }

